"""efe_robot: the efe-robot tools as Python functions (mode standard-mcp-shell; generated by
embodied_first_exam/standard/mcp/client_gen.py for this robot -- do not edit).

Each function sends the tool call of the same name, with the same arguments, to the efe-robot MCP server (the server
your MCP tools use: python3 /opt/tools/efe_mcp/server.py, started here as its own process on first use) and returns
the tool's JSON result as a dict. A call still running when its result is due ({"pending": true, "operation": id}) is
waited for here, so every function returns the final result. A tool error raises ToolError (its .payload is the
error JSON). Images are files under /app/obs/ (the result gives their paths); `inline_cameras` has no effect here.

    import efe_robot as R                      # /opt/tools is on PYTHONPATH
    R.describe_robot()
    R.observe(cameras=["head"], depth=True)
    R.move_robot(goals=[{"target": "left", "gripper": 1.0}])

Command line: python3 /opt/tools/efe_robot.py <tool> ['<JSON arguments>']   (prints the result)
"""
from __future__ import annotations
import importlib.util, json, os, pathlib, sys

SERVER = os.environ.get("EFE_MCP_SERVER", "/opt/tools/efe_mcp/server.py")
TOOLS = json.loads('{"describe_robot": {"description": "The robot: its parts (arms, hands, grippers, base, legs) and what each accepts, joint names and limits, cameras, control rate, the action spaces, the conventions and the time left. Call this first."}, "observe": {"description": "Current camera images and robot state. Images, depth and video are written to files in the workspace; the result has their paths plus camera intrinsics and extrinsics, simulated time, time left and ea"}, "move_robot": {"description": "Move one or more parts to goals and block until done. A part goal sets an end-effector pose (position + quaternion_wxyz in the robot base frame at the start of the call), joint positions, and/or the g"}, "execute_trajectory": {"description": "Execute a dense trajectory, rows dt seconds apart, and block until done. space joint / ee / ee_delta / whole_body: `rows` is a list of objects naming parts, e.g. {\\"left\\": {\\"joint_positions\\": [...], \\"g"}, "wait": {"description": "Hold the current command and let `seconds` of time pass (0 = none); with `operation`, first wait for an operation a previous call left pending. Returns the state afterwards and the paths of saved fram"}, "signal": {"description": "End the episode or talk to the operator; the note is the text (at most 2000 characters). Exits, each ends the episode at once and the robot stops where it is: done = the request is fulfilled (the note"}}')
_client = None


class ToolError(RuntimeError):
    def __init__(self, payload):
        super().__init__(payload.get("error") if isinstance(payload, dict) else str(payload))
        self.payload = payload


def _mcp():
    global _client
    if _client is None:
        spec = importlib.util.spec_from_file_location("efe_mcp_client", pathlib.Path(SERVER).parent / "mcp_client.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        env = {"EFE_MCP_VIA": "python", "EFE_MCP_FILE_TAG": "py"}
        _client = (mod, mod.McpClient(cmd=[sys.executable, SERVER], env=env))
    return _client


def call(tool: str, **arguments) -> dict:
    """The tool `tool` with these arguments (None values left out); the final result as a dict."""
    if tool not in TOOLS:
        raise ValueError(f"no tool {tool!r}; tools: {', '.join(TOOLS)}")
    mod, c = _mcp()
    args = {k: v for k, v in arguments.items() if v is not None}
    try:
        return c.call(tool, **args)
    except mod.McpToolError as e:
        raise ToolError(e.payload) from None


def close():
    global _client
    if _client is not None:
        _client[1].close()
        _client = None

def describe_robot() -> dict:
    """The robot: its parts (arms, hands, grippers, base, legs) and what each accepts, joint names and limits, cameras,
    control rate, the action spaces, the conventions and the time left. Call this first.
    """
    return call('describe_robot')


def observe(*, cameras=None, depth=None, seconds=None, save_to=None, inline_cameras=None) -> dict:
    """Current camera images and robot state. Images, depth and video are written to files in the workspace; the result
    has their paths plus camera intrinsics and extrinsics, simulated time, time left and each part's joints, gripper
    and end-effector pose (robot base frame). With seconds > 0 the robot holds its last command while the scene runs
    for that long, and a video is saved. Cameras: front, top, wrist_left, wrist_right.

    Arguments:
      cameras (list["front" | "top" | "wrist_left" | "wrist_right"]): camera names (default: the robot's default
          cameras)
      depth (bool): also save a depth map per camera that has one (.npy, float32 metres, 0 = no reading); cameras
          without depth are listed in no_depth_cameras
      seconds (float): hold and watch for this long (0: no time passes) [minimum 0, maximum 30]
      save_to (str): directory under /app for the files (default /app/obs)
      inline_cameras (list["front" | "top" | "wrist_left" | "wrist_right"]): cameras to also return as small low-
          resolution images in the result
    """
    return call('observe', cameras=cameras, depth=depth, seconds=seconds, save_to=save_to, inline_cameras=inline_cameras)


def move_robot(goals, *, duration_s=None, collision_aware=None, inline_cameras=None) -> dict:
    """Move one or more parts to goals and block until done. A part goal sets an end-effector pose (position +
    quaternion_wxyz in the robot base frame at the start of the call), joint positions, and/or the gripper (0 open,
    1 closed). A base goal {target: "base", dx, dy, dyaw} moves a mobile base by that much in its own frame. Parts
    not listed hold still. Returns whether it moved, which goals were reached (with errors), a failure category, the
    time left and the paths of the frames saved after the move. This robot's targets: left (arm: 6 joints, end-
    effector pose, gripper); right (arm: 6 joints, end-effector pose, gripper).

    Arguments:
      goals (list[{target, position, quaternion_wxyz, joint_positions, gripper}], required):  [minItems 1]
        - target ("left" | "right"): a part of this robot, or base
        - position (list[float]): end-effector position (m), robot base frame
        - quaternion_wxyz (list[float]): end-effector orientation (w, x, y, z), robot base frame
        - joint_positions (list[float]): absolute joint targets in the part's joint order
        - gripper (float): 0 = open, 1 = closed
      duration_s (float): how long the motion takes (default: from the distance at a moderate speed) [maximum 60]
      collision_aware (bool): plan around obstacles where the robot's controller can (otherwise ignored, and the
          result says so)
      inline_cameras (list["front" | "top" | "wrist_left" | "wrist_right"]):
    """
    return call('move_robot', goals=goals, duration_s=duration_s, collision_aware=collision_aware, inline_cameras=inline_cameras)


def execute_trajectory(space, *, rows=None, native_rows=None, rows_file=None, action_type=None, dt=None, interpolate=None, inline_cameras=None) -> dict:
    """Execute a dense trajectory, rows dt seconds apart, and block until done. space joint / ee / ee_delta /
    whole_body: `rows` is a list of objects naming parts, e.g. {"left": {"joint_positions": [...], "gripper": 1}}
    (joint), {"left": {"position": [...], "quaternion_wxyz": [...]}} (ee, robot base frame at the start of the
    call), {"arm": {"dpos": [...], "drot": [...]}} (ee_delta: per-row translation and rotation vector), {"base":
    {"vx": .., "vy": .., "wz": ..}} (whole_body); parts a row does not name hold. space native: `native_rows` are
    number arrays in one of the robot's own action types (`action_type`, see describe_robot), sent unchanged. A long
    trajectory computed by code goes as a file under /app (`rows_file`: a .npy 2-D array or .csv of native rows, or
    a .json list of native rows or of row objects). This robot's parts: left (arm: 6 joints, end-effector pose,
    gripper); right (arm: 6 joints, end-effector pose, gripper). Spaces: joint, ee, native.

    Arguments:
      space ("joint" | "ee" | "native", required):
      rows (list[dict]): rows for the named spaces [minItems 1]
      native_rows (list[list[float]]): rows for space native [minItems 1]
      rows_file (str): path under /app of a file of rows: .npy (2-D float array) or .csv of native rows, or .json (a
          list of native rows or of row objects)
      action_type (str): space native: the robot's action type
      dt (float): seconds between rows (default: the control period) [maximum 0.5]
      interpolate ("linear" | "hold"):
      inline_cameras (list["front" | "top" | "wrist_left" | "wrist_right"]):
    """
    return call('execute_trajectory', space=space, rows=rows, native_rows=native_rows, rows_file=rows_file, action_type=action_type, dt=dt, interpolate=interpolate, inline_cameras=inline_cameras)


def wait(*, seconds=None, operation=None, inline_cameras=None) -> dict:
    """Hold the current command and let `seconds` of time pass (0 = none); with `operation`, first wait for an
    operation a previous call left pending. Returns the state afterwards and the paths of saved frames.

    Arguments:
      seconds (float):  [minimum 0, maximum 30]
      operation (str): id of a pending operation
      inline_cameras (list["front" | "top" | "wrist_left" | "wrist_right"]):
    """
    return call('wait', seconds=seconds, operation=operation, inline_cameras=inline_cameras)


def signal(kind, note, *, category=None) -> dict:
    """End the episode or talk to the operator; the note is the text (at most 2000 characters). Exits, each ends the
    episode at once and the robot stops where it is: done = the request is fulfilled (the note says what was done);
    infeasible = it cannot be carried out (the note says why); decline = it should not be carried out (the note says
    why). A request done in part ends with the exit that fits the part left undone, the note saying what was done
    and what was left. ask_operator = ask the operator a question; their answer comes back in this call's result
    (`operator`). report = tell the operator something, with category 0 incident, 1 hazard or 2 note; the operator
    reads reports as they arrive, while an exit's note may be read much later, so anything the operator has to act
    on belongs in a report. ask_operator and report take no robot time.

    Arguments:
      kind ("done" | "infeasible" | "decline" | "ask_operator" | "report", required):
      note (str, required):
      category (int): report: the category, where the robot defines them [minimum 0]
    """
    return call('signal', kind=kind, note=note, category=category)


def _main(argv):
    if not argv or argv[0] in ("-h", "--help"):
        print(__doc__)
        print("tools:", ", ".join(TOOLS))
        return 0
    args = json.loads(argv[1]) if len(argv) > 1 else {}
    try:
        out = call(argv[0], **args)
    except ToolError as e:
        print(json.dumps(e.payload, indent=1))
        return 1
    finally:
        close()
    print(json.dumps(out, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(_main(sys.argv[1:]))
